#include <vector>
#include <unordered_map>

class Solution {
public:
    int countSingleBlockIntegers(std::vector<int>& nums) {
        std::unordered_map<int, int> first, last, count;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (first.find(nums[i]) == first.end()) {
                first[nums[i]] = i;
            }
            last[nums[i]] = i;
            count[nums[i]]++;
        }
        int ans = 0;
        for (auto const& [x, cnt] : count) {
            if (last[x] - first[x] + 1 == cnt) {
                ans++;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countSingleBlockIntegers(int[] nums) {
        Map<Integer, Integer> first = new HashMap<>();
        Map<Integer, Integer> last = new HashMap<>();
        Map<Integer, Integer> count = new HashMap<>();

        for (int i = 0; i < nums.length; i++) {
            first.putIfAbsent(nums[i], i);
            last.put(nums[i], i);
            count.put(nums[i], count.getOrDefault(nums[i], 0) + 1);
        }

        int ans = 0;
        for (int x : count.keySet()) {
            if (last.get(x) - first.get(x) + 1 == count.get(x)) {
                ans++;
            }
        }
        return ans;
    }
}

